def local_datetime(value):
    if not value:
        return ""
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return value.astimezone(LOCAL_TZ).strftime("%d/%m/%Y %H:%M GMT-3")


def status_track_datetime(value):
    if not value:
        return ""
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    local_value = value.astimezone(LOCAL_TZ)
    hour = local_value.strftime("%I").lstrip("0") or "0"
    return f"{local_value.strftime('%d/%m/%Y')} · {hour}:{local_value.strftime('%M')} {local_value.strftime('%p').lower()}"


def export_datetime(value):
    if not value:
        return ""
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return value.astimezone(LOCAL_TZ).strftime("%d/%m/%Y %H:%M")


def normalize_logistics_fee(value):
    raw_value = (value or "").strip()
    if not raw_value:
        return None, None
    if not re.fullmatch(r"\d+(,\d+)?", raw_value):
        return None, "Fee must be a positive number."
    try:
        amount = Decimal(raw_value.replace(",", "."))
    except InvalidOperation:
        return None, "Fee must be a positive number."
    integer_part = int(amount.to_integral_value(rounding=ROUND_FLOOR))
    decimal_part = amount - Decimal(integer_part)
    if decimal_part > Decimal("0.50"):
        integer_part += 1
    return integer_part, None


def logistics_concepts_have_data(concepts):
    return any(
        concept.provider
        or concept.fee is not None
        or concept.status != "Pending"
        or concept.currency != "ARS"
        or concept.notes
        for concept in concepts
    )


def logistics_enabled_for_session(session_id):
    for model in (ExamSessionSupervisorAssignment, ExamSessionExaminerAssignment, ExamSessionInternAssignment):
        if model.query.filter_by(exam_session_id=session_id, logistics_enabled=True).first():
            return True
    return False


def logistics_readiness_contract(assignments, concepts, logistics_config=None):
    required_member_ids = sorted({
        assignment.team_member_id
        for assignment in assignments
        if assignment.team_member_id is not None and assignment.logistics_enabled
    })
    has_enabled_assignments = bool(required_member_ids)
    active_concepts = list(concepts or [])
    logistics_files_url = (logistics_config.logistics_files_url or "").strip() if logistics_config else ""
    has_files_url = bool(logistics_files_url and is_valid_url(logistics_files_url))
    blocking_concepts = [
        {
            "id": concept.id,
            "status": concept.status,
            "provider": concept.provider,
        }
        for concept in active_concepts
        if concept.status != "Confirmed"
    ]
    confirmed_concepts = sum(1 for concept in active_concepts if concept.status == "Confirmed")
    blockers = []

    if not has_enabled_assignments and not active_concepts:
        status = "not_applicable"
        ready = True
    elif has_enabled_assignments and not active_concepts:
        status = "configuration_required"
        ready = False
        blockers.append({
            "code": "LOGISTICS_CONCEPTS_MISSING",
            "message": "Logistics is enabled but no logistics concepts have been configured.",
        })
    elif blocking_concepts:
        status = "in_progress"
        ready = False
        blockers.append({
            "code": "LOGISTICS_CONCEPTS_PENDING",
            "message": "Waiting for all logistics concepts to be confirmed.",
        })
    else:
        status = "confirmed"
        ready = True

    final_email_ready = ready
    if has_enabled_assignments and ready and not has_files_url:
        final_email_ready = False
        blockers.append({
            "code": "LOGISTICS_FILES_URL_MISSING",
            "message": "Add the Check logistics files link before copying the final email.",
        })

    return {
        "applies": has_enabled_assignments or bool(active_concepts),
        "status": status,
        "ready": ready,
        "final_email_ready": final_email_ready,
        "required_member_ids": required_member_ids,
        "total_concepts": len(active_concepts),
        "confirmed_concepts": confirmed_concepts,
        "blocking_concepts": blocking_concepts,
        "has_files_url": has_files_url,
        "blockers": blockers,
    }


def logistics_email_blocker_message(contract):
    blocker_codes = {blocker["code"] for blocker in contract.get("blockers", [])}
    if "LOGISTICS_CONCEPTS_MISSING" in blocker_codes:
        return "Logistics details must be configured before copying the final email."
    if "LOGISTICS_FILES_URL_MISSING" in blocker_codes:
        return "Add the Check logistics files link before copying the final email."
    if "LOGISTICS_CONCEPTS_PENDING" in blocker_codes:
        return "Waiting for all logistics concepts to be confirmed."
    return "Email copy unavailable"


def empty_staffing_counts():
    return {
        "required": 0,
        "assigned": 0,
        "open_positions": 0,
        "pending_assigned": 0,
        "sent": 0,
        "confirmed": 0,
    }


def normalize_participation_status(status):
    status = (status or "Pending").strip()
    return LEGACY_PARTICIPATION_STATUS_MAP.get(status, status)


def normalize_assignment_logistics_type(logistics_type, legacy_enabled=False):
    logistics_type = (logistics_type or "").strip()
    if logistics_type in EXAM_SESSION_LOGISTICS_TYPE_OPTIONS:
        return logistics_type
    if legacy_enabled:
        return "Simple logistics"
    return "Does not apply"


def participation_status_is_in_progress(status):
    return normalize_participation_status(status) in {
        "Pre-confirmation sent",
        "Pre-confirmed",
        "Official confirmation sent",
    }


def staffing_readiness_contract(supervisor_assignments=None, examiner_assignments=None, intern_assignments=None, session_record=None):
    role_sources = {
        "Supervisor": list(supervisor_assignments or []),
        "Examiner": list(examiner_assignments or []),
        "Intern": list(intern_assignments or []),
    }
    totals = empty_staffing_counts()
    by_role = {}
    open_position_details = []
    blockers = []
    invalid_found = False
    if session_record and session_record.emergency_contact_member_id:
        counts = empty_staffing_counts()
        participation_status = normalize_participation_status(session_record.emergency_contact_participation_status)
        counts["required"] = 1
        counts["assigned"] = 1
        if participation_status == "Pending":
            counts["pending_assigned"] = 1
        elif participation_status == "Declined":
            counts["pending_assigned"] = 1
            blockers.append({
                "code": "STAFF_DECLINED",
                "role": "Emergency contact",
                "assignment_id": session_record.id,
                "message": "Emergency contact declined participation and needs follow-up.",
            })
        elif participation_status == "Cancelled":
            counts["pending_assigned"] = 1
            blockers.append({
                "code": "STAFF_CANCELLED",
                "role": "Emergency contact",
                "assignment_id": session_record.id,
                "message": "Emergency contact participation was cancelled and needs follow-up.",
            })
        elif participation_status_is_in_progress(participation_status):
            counts["sent"] = 1
        elif participation_status == "Confirmed":
            counts["confirmed"] = 1
        else:
            invalid_found = True
            blockers.append({
                "code": "INVALID_PARTICIPATION_STATUS",
                "role": "Emergency contact",
                "assignment_id": session_record.id,
                "message": "Emergency contact has an invalid participation status.",
            })
        counts["ready"] = counts["confirmed"] == counts["required"]
        by_role["Emergency contact"] = counts
        for key in totals:
            totals[key] += counts[key]

    for role, assignments in role_sources.items():
        counts = empty_staffing_counts()
        for assignment in assignments:
            assignment_id = getattr(assignment, "id", None)
            team_member_id = getattr(assignment, "team_member_id", None)
            potential_entry_id = getattr(assignment, "potential_entry_id", None)
            participation_status = normalize_participation_status(getattr(assignment, "participation_status", "Pending"))
            has_member = team_member_id is not None or potential_entry_id is not None

            counts["required"] += 1
            if has_member:
                counts["assigned"] += 1
                if participation_status == "Pending":
                    counts["pending_assigned"] += 1
                elif participation_status == "Declined":
                    counts["pending_assigned"] += 1
                    blockers.append({
                        "code": "STAFF_DECLINED",
                        "role": role,
                        "assignment_id": assignment_id,
                        "message": f"{role} declined participation and needs follow-up.",
                    })
                elif participation_status == "Cancelled":
                    counts["pending_assigned"] += 1
                    blockers.append({
                        "code": "STAFF_CANCELLED",
                        "role": role,
                        "assignment_id": assignment_id,
                        "message": f"{role} participation was cancelled and needs follow-up.",
                    })
                elif participation_status_is_in_progress(participation_status):
                    counts["sent"] += 1
                elif participation_status == "Confirmed":
                    counts["confirmed"] += 1
                else:
                    invalid_found = True
                    blockers.append({
                        "code": "INVALID_PARTICIPATION_STATUS",
                        "role": role,
                        "assignment_id": assignment_id,
                        "message": f"{role} has an invalid participation status.",
                    })
            else:
                counts["open_positions"] += 1
                open_position_details.append({
                    "assignment_id": assignment_id,
                    "role": role,
                })
                if participation_status == "Pending":
                    blockers.append({
                        "code": "OPEN_STAFF_POSITION",
                        "role": role,
                        "assignment_id": assignment_id,
                        "message": f"A {role} position still needs to be filled.",
                    })
                else:
                    invalid_found = True
                    blockers.append({
                        "code": "INVALID_EMPTY_STAFF_POSITION_STATUS",
                        "role": role,
                        "assignment_id": assignment_id,
                        "message": "A staff position without an assigned member must remain Pending.",
                    })

        counts["ready"] = (
            counts["required"] == 0
            or (
                counts["open_positions"] == 0
                and counts["assigned"] == counts["required"]
                and counts["confirmed"] == counts["required"]
            )
        )
        by_role[role] = counts
        for key in totals:
            totals[key] += counts[key]

    if totals["required"] == 0:
        status = "not_configured"
        blockers.append({
            "code": "STAFFING_NOT_CONFIGURED",
            "message": "Configure at least one staff position before copying the final email.",
        })
    elif invalid_found:
        status = "invalid"
    elif totals["open_positions"] > 0:
        status = "open_positions"
    elif totals["pending_assigned"] > 0 or totals["sent"] > 0:
        status = "awaiting_confirmations"
        blockers.append({
            "code": "STAFFING_AWAITING_CONFIRMATIONS",
            "message": "Waiting for all staff members to confirm their participation.",
        })
    else:
        status = "confirmed"

    ready = (
        totals["required"] > 0
        and totals["open_positions"] == 0
        and totals["assigned"] == totals["required"]
        and totals["confirmed"] == totals["required"]
        and not invalid_found
    )

    return {
        "status": status,
        "ready": ready,
        "final_email_ready": ready,
        "totals": totals,
        "by_role": by_role,
        "open_position_details": open_position_details,
        "blockers": blockers,
    }


def staffing_email_blocker_message(contract):
    blocker_codes = {blocker["code"] for blocker in contract.get("blockers", [])}
    if "STAFFING_NOT_CONFIGURED" in blocker_codes:
        return "Configure at least one staff position before copying the final email."
    if "OPEN_STAFF_POSITION" in blocker_codes:
        return "Assign a staff member to every required role before copying the final email."
    if "STAFFING_AWAITING_CONFIRMATIONS" in blocker_codes:
        return "Waiting for all staff members to confirm their participation."
    if blocker_codes:
        return "A staff assignment needs to be corrected before copying the final email."
    return "Email copy unavailable"


def persisted_staff_confirmed(*assignment_groups):
    if len(assignment_groups) == 1:
        assignment_groups = (assignment_groups[0], [], [])
    return staffing_readiness_contract(*assignment_groups)["ready"]


def final_email_ready(staffing_contract, logistics_contract):
    return bool(
        staffing_contract.get("final_email_ready")
        and logistics_contract.get("final_email_ready")
    )


def pluralize_count(count, singular, plural=None):
    label = singular if count == 1 else (plural or f"{singular}s")
    return f"{count} {label}"


def exam_session_emergency_contact_decision_ready(session_record):
    if not session_record:
        return False
    return bool(session_record.emergency_contact_required or session_record.emergency_contact_not_required)


def exam_session_shipment_recipient_ready(session_record, assignments):
    if not session_record or session_record.format != "Onsite":
        return True
    return any(assignment.team_member_id and assignment.is_shipment_recipient for assignment in assignments or [])


def monthly_candidate_requirement_contracts(session_ids):
    session_ids = [session_id for session_id in session_ids if session_id is not None]
    if not session_ids:
        return {}
    sessions_by_id = {
        session_record.id: session_record
        for session_record in ExamSession.query.filter(ExamSession.id.in_(session_ids)).all()
    }
    active_months_by_session = {session_id: set() for session_id in session_ids}
    totals_by_session_month = {}
    for session_id, month, total_candidates in (
        db.session.query(
            ExamSessionMonthlyCandidateTotal.exam_session_id,
            ExamSessionMonthlyCandidateTotal.month,
            ExamSessionMonthlyCandidateTotal.total_candidates,
        )
        .filter(ExamSessionMonthlyCandidateTotal.exam_session_id.in_(session_ids))
        .all()
    ):
        active_months_by_session.setdefault(session_id, set()).add(month)
        totals_by_session_month[(session_id, month)] = total_candidates or 0
    for session_id, month in (
        db.session.query(
            ExamSessionMonthlyRegistration.exam_session_id,
            ExamSessionMonthlyRegistration.month,
        )
        .filter(ExamSessionMonthlyRegistration.exam_session_id.in_(session_ids))
        .distinct()
        .all()
    ):
        active_months_by_session.setdefault(session_id, set()).add(month)

    contracts = {}
    for session_id in session_ids:
        session_record = sessions_by_id.get(session_id)
        required = session_record.minimum_candidates_required if session_record else 30
        required = required if required is not None else 30
        latest_month = max(active_months_by_session.get(session_id, set()) or [0])
        current = totals_by_session_month.get((session_id, latest_month), 0) if latest_month else 0
        contracts[session_id] = {
            "ready": current >= required,
            "current": current,
            "required": required,
            "latest_month": latest_month or None,
        }
    return contracts


def monthly_registration_close_requirement(session_record):
    if not session_record:
        return {
            "ready": False,
            "current": None,
            "required": 30,
            "latest_month": None,
        }
    latest_total_month = (
        db.session.query(db.func.max(ExamSessionMonthlyCandidateTotal.month))
        .filter_by(exam_session_id=session_record.id)
        .scalar()
    )
    latest_registration_month = (
        db.session.query(db.func.max(ExamSessionMonthlyRegistration.month))
        .filter_by(exam_session_id=session_record.id)
        .scalar()
    )
    latest_months = [month for month in (latest_total_month, latest_registration_month) if month is not None]
    latest_month = max(latest_months) if latest_months else None
    required = session_record.minimum_candidates_required
    required = required if required is not None else 30
    total_record = None
    if latest_month is not None:
        total_record = ExamSessionMonthlyCandidateTotal.query.filter_by(
            exam_session_id=session_record.id,
            month=latest_month,
        ).first()
    current = total_record.total_candidates if total_record else None
    return {
        "ready": current is not None and current >= required,
        "current": current,
        "required": required,
        "latest_month": latest_month,
    }


def monthly_registration_status(session_record, requirement=None):
    if session_record and session_record.monthly_registrations_closed:
        return "Closed"
    requirement = requirement or monthly_registration_close_requirement(session_record)
    if requirement["latest_month"] is None:
        return "Pending"
    return "Achieved" if requirement["ready"] else "In progress"


def return_package_requirements_for_session(session_record):
    if not session_record:
        return []
    latest_month = (
        db.session.query(db.func.max(ExamSessionMonthlyRegistration.month))
        .filter_by(exam_session_id=session_record.id)
        .scalar()
    )
    if latest_month is None:
        return []
    registrations = ExamSessionMonthlyRegistration.query.filter_by(
        exam_session_id=session_record.id,
        month=latest_month,
    ).all()
    registrations_by_module = {
        registration.module: registration.registration_number or 0
        for registration in registrations
    }
    has_reading_and_writing = registrations_by_module.get("Reading and writing", 0) > 0
    has_listening_or_speaking = (
        registrations_by_module.get("Listening and speaking", 0) > 0
        or registrations_by_module.get("Speaking", 0) > 0
    )
    requirements = []
    if has_reading_and_writing:
        requirements.extend([
            "1 submitted Reading and writing modules.",
            "1 absent Reading and writing modules.",
        ])
    if has_listening_or_speaking:
        requirements.extend([
            "1 submitted Listening and speaking modules.",
            "1 absent Listening and speaking modules.",
        ])
    return requirements


def staff_members_pending_id_for_session(session_record, assignments=None):
    if not session_record and not assignments:
        return []
    seen_member_ids = set()
    staff_members = []
    if session_record and session_record.emergency_contact_member:
        staff_members.append(session_record.emergency_contact_member)
    for assignment in assignments or []:
        staff_member = getattr(assignment, "team_member", None)
        if staff_member:
            staff_members.append(staff_member)
    pending_staff_members = []
    for staff_member in staff_members:
        if not staff_member or staff_member.id in seen_member_ids:
            continue
        seen_member_ids.add(staff_member.id)
        if not getattr(staff_member, "id_issued", False):
            pending_staff_members.append(staff_member)
    return sorted(pending_staff_members, key=lambda value: value.full_name.casefold())


def staff_member_confirmation_by_id(session_record, assignments=None):
    confirmation_by_id = {}
    if session_record and session_record.emergency_contact_member_id:
        confirmation_by_id[session_record.emergency_contact_member_id] = False
    for assignment in assignments or []:
        staff_member_id = getattr(assignment, "team_member_id", None)
        if not staff_member_id:
            continue
        is_confirmed = normalize_participation_status(getattr(assignment, "participation_status", "")) == "Confirmed"
        confirmation_by_id[staff_member_id] = confirmation_by_id.get(staff_member_id, False) or is_confirmed
    return confirmation_by_id


def staff_member_id_requirement_payload(staff_member, is_confirmed=True):
    return {
        "id": staff_member.id,
        "title": staff_member.title or "",
        "name": staff_member.full_name,
        "roles": staff_member.roles_list(),
        "is_confirmed": bool(is_confirmed),
    }


def staff_member_id_snapshot_for_session(session_record):
    if not session_record:
        return []
    try:
        snapshot = json.loads(session_record.staff_member_ids_snapshot or "[]")
    except (TypeError, ValueError, json.JSONDecodeError):
        return []
    if not isinstance(snapshot, list):
        return []
    clean_snapshot = []
    for item in snapshot:
        if not isinstance(item, dict):
            continue
        name = (item.get("name") or "").strip()
        if not name:
            continue
        clean_snapshot.append({
            "id": item.get("id"),
            "title": (item.get("title") or "").strip(),
            "name": name,
            "roles": [str(role).strip() for role in item.get("roles", []) if str(role).strip()],
            "is_confirmed": bool(item.get("is_confirmed", True)),
        })
    return clean_snapshot


def staff_member_id_requirements_for_session(session_record, assignments=None):
    requirements = []
    confirmation_by_id = staff_member_confirmation_by_id(session_record, assignments)
    for staff_member in staff_members_pending_id_for_session(session_record, assignments):
        requirements.append(staff_member_id_requirement_payload(
            staff_member,
            is_confirmed=confirmation_by_id.get(staff_member.id, False),
        ))
    return requirements or staff_member_id_snapshot_for_session(session_record)


def inclusion_final_items_for_session(session_record, supervisor_assignments=None):
    if not session_record:
        return {
            "total_candidates": 0,
            "supervisor_count": 0,
            "schedule_copy_label": "copies",
        }
    latest_total_month = (
        db.session.query(db.func.max(ExamSessionMonthlyCandidateTotal.month))
        .filter_by(exam_session_id=session_record.id)
        .scalar()
    )
    total_candidates = 0
    if latest_total_month is not None:
        total_record = ExamSessionMonthlyCandidateTotal.query.filter_by(
            exam_session_id=session_record.id,
            month=latest_total_month,
        ).first()
        total_candidates = total_record.total_candidates if total_record else 0
    assigned_supervisors = [
        assignment
        for assignment in supervisor_assignments or []
        if getattr(assignment, "team_member_id", None) or getattr(assignment, "potential_entry_id", None)
    ]
    supervisor_count = len(assigned_supervisors)
    return {
        "total_candidates": total_candidates or 0,
        "supervisor_count": supervisor_count,
        "schedule_copy_label": "copy" if supervisor_count == 1 else "copies",
    }


SESSION_IDENTIFICATION_LABEL_SIZE = (280.63, 161.575)


def session_identification_label_supervisor(supervisor_assignments):
    assigned = [
        assignment for assignment in supervisor_assignments or []
        if getattr(assignment, "team_member_id", None)
    ]
    if len(assigned) == 1:
        assignment = assigned[0]
        return assignment.team_member or AcademicStaff.query.get(assignment.team_member_id)
    supervisor = get_exam_session_shipment_recipient_supervisor(assigned)
    return supervisor


def session_identification_label_payload(session_record):
    supervisor_assignments = ExamSessionSupervisorAssignment.query.filter_by(
        exam_session_id=session_record.id,
    ).order_by(ExamSessionSupervisorAssignment.id.asc()).all()
    supervisor = session_identification_label_supervisor(supervisor_assignments)
    if not supervisor:
        return None, "Supervisor is required to generate the session identification label."
    fields = {
        "EXAM SESSION": session_record.exam_session_name,
        "DATE": long_session_date_filter(session_record.session_date),
        "FULL ADDRESS": session_record.full_address_google_maps,
        "CITY": session_record.city,
        "PROVINCE": session_record.province,
        "SUPERVISOR": supervisor.full_name,
    }
    if any(not (value or "").strip() for value in fields.values()):
        return None, "Session information is incomplete. Please complete the session details before generating the identification label."
    return fields, ""


def pdf_text(value):
    text = re.sub(r"\s+", " ", str(value or "").strip())
    return text.encode("latin-1", "replace").decode("latin-1")


def pdf_escape(value):
    text = pdf_text(value)
    return text.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def pdf_text_width(value, font_size):
    return len(pdf_text(value)) * font_size * 0.47


def pdf_wrap(value, font_size, max_width, max_lines=2):
    words = pdf_text(value).split()
    if not words:
        return [""]
    lines = []
    current = ""
    for word in words:
        candidate = f"{current} {word}".strip()
        if current and pdf_text_width(candidate, font_size) > max_width:
            lines.append(current)
            current = word
            if len(lines) >= max_lines:
                break
        else:
            current = candidate
    if len(lines) < max_lines and current:
        lines.append(current)
    if len(lines) > max_lines:
        lines = lines[:max_lines]
    return lines


def pdf_command_text(x, y, value, font="/F1", size=8):
    return f"BT {font} {size} Tf {x:.2f} {y:.2f} Td ({pdf_escape(value)}) Tj ET"


def build_pdf_document_pages(width, height, pages_commands):
    page_count = len(pages_commands)
    page_object_ids = [5 + (index * 2) for index in range(page_count)]
    objects = [
        b"<< /Type /Catalog /Pages 2 0 R >>",
        f"<< /Type /Pages /Kids [{' '.join(f'{page_id} 0 R' for page_id in page_object_ids)}] /Count {page_count} /MediaBox [0 0 {width:.3f} {height:.3f}] >>".encode("ascii"),
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>",
    ]
    for index, commands in enumerate(pages_commands):
        page_id = 5 + (index * 2)
        content_id = page_id + 1
        content = "\n".join(commands).encode("latin-1", "replace")
        objects.extend([
            f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {width:.3f} {height:.3f}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents {content_id} 0 R >>".encode("ascii"),
            b"<< /Length " + str(len(content)).encode("ascii") + b" >>\nstream\n" + content + b"\nendstream",
        ])
    pdf = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = [0]
    for index, obj in enumerate(objects, start=1):
        offsets.append(len(pdf))
        pdf.extend(f"{index} 0 obj\n".encode("ascii"))
        pdf.extend(obj)
        pdf.extend(b"\nendobj\n")
    xref_offset = len(pdf)
    pdf.extend(f"xref\n0 {len(objects) + 1}\n".encode("ascii"))
    pdf.extend(b"0000000000 65535 f \n")
    for offset in offsets[1:]:
        pdf.extend(f"{offset:010d} 00000 n \n".encode("ascii"))
    pdf.extend(
        f"trailer\n<< /Size {len(objects) + 1} /Root 1 0 R >>\nstartxref\n{xref_offset}\n%%EOF\n".encode("ascii")
    )
    return bytes(pdf)


def build_pdf_document(width, height, commands):
    return build_pdf_document_pages(width, height, [commands])


def build_session_identification_label_pdf(fields):
    width, height = SESSION_IDENTIFICATION_LABEL_SIZE
    commands = [
        "0 0 0 RG 0 0 0 rg",
        "0.8 w",
        f"5 5 {width - 10:.2f} {height - 10:.2f} re S",
        "1.2 w",
        f"12 {height - 36:.2f} {width - 24:.2f} 24 re S",
        pdf_command_text(18, height - 23, "PATH EXAMINATIONS", "/F2", 11),
        pdf_command_text(18, height - 33, "SESSION IDENTIFICATION LABEL", "/F1", 6.5),
        f"12 {height - 44:.2f} m {width - 12:.2f} {height - 44:.2f} l S",
    ]
    session_lines = pdf_wrap(fields["EXAM SESSION"], 10.5, width - 32, max_lines=2)
    y = height - 55
    commands.append(pdf_command_text(18, y, "EXAM SESSION", "/F2", 5.5))
    y -= 10
    for line in session_lines:
        commands.append(pdf_command_text(18, y, line, "/F2", 10.5))
        y -= 11
    commands.append(f"12 {y + 4:.2f} m {width - 12:.2f} {y + 4:.2f} l S")
    grid_top = y - 7
    left_x = 18
    right_x = width / 2 + 6
    row_gap = 24
    grid_fields = [
        ("DATE", fields["DATE"], left_x, grid_top),
        ("SUPERVISOR", fields["SUPERVISOR"], right_x, grid_top),
        ("FULL ADDRESS", fields["FULL ADDRESS"], left_x, grid_top - row_gap),
        ("CITY", fields["CITY"], right_x, grid_top - row_gap),
        ("PROVINCE", fields["PROVINCE"], left_x, grid_top - row_gap * 2),
    ]
    for label, value, x, field_y in grid_fields:
        commands.append(pdf_command_text(x, field_y, label, "/F2", 5.2))
        for index, line in enumerate(pdf_wrap(value, 7.1, (width / 2) - 24, max_lines=2)):
            commands.append(pdf_command_text(x, field_y - 8 - (index * 8), line, "/F1", 7.1))
    commands.append(f"12 16 m {width - 12:.2f} 16 l S")
    commands.append(pdf_command_text(18, 9, "PRINT IDENTIFICATION LABEL AND AFFIX IT TO TOP OF SEALED SESSION BOX", "/F2", 5.2))
    return build_pdf_document(width, height, commands)


def bundle_label_payload(bundle):
    if not bundle:
        return None, "Bundle information is incomplete. Please complete the bundle details before generating the label."
    if not shipment_bundle_display_number(bundle):
        return None, "Bundle information is incomplete. Please complete the bundle details before generating the label."
    if not bundle.supervisor:
        return None, "Supervisor is required to generate the bundle label."
    sessions = shipment_bundle_sessions(bundle)
    if not sessions:
        return None, "This bundle does not include any sessions."
    clean_sessions = []
    for session_record in sorted(sessions, key=lambda item: (item.session_date or datetime.max.date(), (item.exam_session_name or "").casefold())):
        if not (session_record.exam_session_name or "").strip():
            return None, "Bundle information is incomplete. Please complete the bundle details before generating the label."
        detail_parts = [
            session_date_filter(session_record.session_date) if session_record.session_date else "",
            session_record.city,
            session_record.province,
        ]
        clean_sessions.append({
            "name": session_record.exam_session_name.strip(),
            "details": ", ".join(part.strip() for part in detail_parts if (part or "").strip()),
        })
    return {
        "bundle_number": shipment_bundle_display_number(bundle).lstrip("#"),
        "supervisor": bundle.supervisor.full_name,
        "session_count": str(len(clean_sessions)),
        "delivery_address": ", ".join(part.strip() for part in [
            bundle.delivery_address,
            bundle.delivery_city,
            bundle.delivery_province,
        ] if (part or "").strip()) or "Not set",
        "sessions": clean_sessions,
    }, ""


def build_bundle_label_pdf(payload):
    width, height = SESSION_IDENTIFICATION_LABEL_SIZE
    sessions_per_page = 9
    session_pages = [
        payload["sessions"][index:index + sessions_per_page]
        for index in range(0, len(payload["sessions"]), sessions_per_page)
    ] or [[]]
    pages = []
    for page_index, page_sessions in enumerate(session_pages):
        commands = [
            "0 0 0 RG 0 0 0 rg",
            "0.8 w",
            f"5 5 {width - 10:.2f} {height - 10:.2f} re S",
            "1.2 w",
            f"12 {height - 34:.2f} {width - 24:.2f} 22 re S",
            pdf_command_text(18, height - 21, "PATH EXAMINATIONS", "/F2", 10.5),
            pdf_command_text(18, height - 31, "BUNDLE LABEL", "/F1", 6.5),
            pdf_command_text(width - 88, height - 23, "BUNDLE", "/F2", 5.5),
            pdf_command_text(width - 88, height - 33, payload["bundle_number"], "/F2", 12),
            f"12 {height - 42:.2f} m {width - 12:.2f} {height - 42:.2f} l S",
        ]
        y = height - 52
        left_x = 18
        middle_x = 95
        right_x = 168
        summary_width = 72
        summary = [
            ("SUPERVISOR", payload["supervisor"], left_x, y),
            ("SESSIONS", payload["session_count"], middle_x, y),
            ("DELIVERY", payload["delivery_address"], right_x, y),
        ]
        for label, value, x, row_y in summary:
            commands.append(pdf_command_text(x, row_y, label, "/F2", 5.1))
            for line_index, line in enumerate(pdf_wrap(value, 6.1, summary_width, max_lines=2)):
                commands.append(pdf_command_text(x, row_y - 8 - (line_index * 6.5), line, "/F1", 6.1))
        sessions_top = y - 26
        commands.append(f"12 {sessions_top + 6:.2f} m {width - 12:.2f} {sessions_top + 6:.2f} l S")
        sessions_label = "SESSIONS INCLUDED"
        if len(session_pages) > 1:
            sessions_label = f"{sessions_label} ({page_index + 1}/{len(session_pages)})"
        commands.append(pdf_command_text(18, sessions_top, sessions_label, "/F2", 5.8))
        for row, session_item in enumerate(page_sessions):
            item_number = (page_index * sessions_per_page) + row + 1
            current_y = sessions_top - 8 - (row * 7.1)
            details = f", {session_item['details']}" if session_item["details"] else ""
            title = f"{item_number}. {session_item['name']}{details}"
            for line in pdf_wrap(title, 6.1, width - 34, max_lines=1):
                commands.append(pdf_command_text(18, current_y, line, "/F1", 6.1))
        commands.append(f"12 14 m {width - 12:.2f} 14 l S")
        commands.append(pdf_command_text(18, 8, "PRINT BUNDLE LABEL AND AFFIX IT TO TOP OF BUNDLE", "/F2", 5.2))
        pages.append(commands)
    return build_pdf_document_pages(width, height, pages)


def exam_session_pending_status_tooltip(staffing_contract, logistics_contract, session_record=None, assignments=None, candidate_contract=None):
    missing_items = []
    staffing_status = staffing_contract.get("status")
    staffing_totals = staffing_contract.get("totals", {})
    if staffing_status == "not_configured":
        missing_items.append("Add at least one staff position.")
    elif staffing_status == "invalid":
        missing_items.append("Correct invalid staff rows.")
    elif staffing_status == "open_positions":
        open_positions = staffing_totals.get("open_positions", 0)
        missing_items.append(
            f"Assign staff members to {pluralize_count(open_positions, 'open staff position')}."
        )
    elif staffing_status == "awaiting_confirmations":
        pending = staffing_totals.get("pending_assigned", 0)
        sent = staffing_totals.get("sent", 0)
        status_parts = []
        if pending:
            status_parts.append(pluralize_count(pending, "Pending staff member"))
        if sent:
            status_parts.append(pluralize_count(sent, "confirmation in progress", "confirmations in progress"))
        suffix = f" ({', '.join(status_parts)})" if status_parts else ""
        missing_items.append(f"Confirm all assigned staff{suffix}.")

    logistics_status = logistics_contract.get("status")
    if logistics_status == "configuration_required":
        blocker_codes = {blocker["code"] for blocker in logistics_contract.get("blockers", [])}
        if "LOGISTICS_CONCEPTS_MISSING" in blocker_codes:
            missing_items.append("Add at least one logistics concept.")
        if "LOGISTICS_FILES_URL_MISSING" in blocker_codes:
            missing_items.append("Add the Check logistics files link.")
        if "LOGISTICS_CONCEPTS_PENDING" in blocker_codes:
            pending = len(logistics_contract.get("blocking_concepts", []))
            missing_items.append(f"Confirm {pluralize_count(pending, 'logistics concept')}.")
    elif logistics_status == "in_progress":
        pending = len(logistics_contract.get("blocking_concepts", []))
        missing_items.append(f"Confirm {pluralize_count(pending, 'logistics concept')}.")
    elif logistics_status == "confirmed":
        blocker_codes = {blocker["code"] for blocker in logistics_contract.get("blockers", [])}
        if "LOGISTICS_FILES_URL_MISSING" in blocker_codes:
            missing_items.append("Add the Check logistics files link.")

    if session_record and not exam_session_emergency_contact_decision_ready(session_record):
        missing_items.append("Select Emergency contact required or Emergency contact NOT required.")
    if session_record and session_record.date_confirmation_status != "Confirmed":
        missing_items.append("Confirm the session date.")
    if session_record and not exam_session_shipment_recipient_ready(session_record, assignments or []):
        missing_items.append("Assign Receives shipment for onsite sessions.")
    if candidate_contract and not candidate_contract.get("ready"):
        missing_items.append(
            "Minimum number of candidates not met: "
            f"{candidate_contract.get('current', 0)}/{candidate_contract.get('required', 30)}"
        )

    if not missing_items:
        missing_items.append("Confirm every staff assignment and logistics concept.")
    return "Missing for Confirmed:\n- " + "\n- ".join(missing_items)


