IMPORT_REQUIRED_HEADERS = {
    "Status",
    "Title",
    "Full name",
    "Roles",
    "Phone",
    "Email",
    "Has a car",
    "Full address",
    "City",
    "Province",
    "Country",
    "CV",
    "Account ID",
    "Account owner",
    "Profile picture",
    "Started in",
}
IMPORT_OPTIONAL_HEADERS = {
    "Street name",
    "Street number",
    "Postcode",
    "Location point",
    "History",
    "Dietary requirements",
    "Sessions",
    "Updated on",
    "Seniority",
}
IMPORT_HEADERS = IMPORT_REQUIRED_HEADERS | IMPORT_OPTIONAL_HEADERS
IMPORT_STATUS_OPTIONS = set(EDIT_STATUS_OPTIONS)
IMPORT_HAS_CAR_OPTIONS = {"Yes", "No"}
EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def import_batch_dir():
    path = os.path.join(current_app.instance_path, "import_batches")
    os.makedirs(path, exist_ok=True)
    return path


def import_batch_path(token):
    return os.path.join(import_batch_dir(), f"{token}.json")


def cell_text(value):
    if value is None:
        return ""
    return str(value).strip()


def normalize_roles(value):
    return [role.strip() for role in value.split(",") if role.strip()]


def normalize_yes_no(value):
    normalized = value.strip().lower()
    if normalized == "yes":
        return "Yes"
    if normalized == "no":
        return "No"
    return value.strip()


def normalize_status(value):
    normalized = value.strip().lower()
    for status in IMPORT_STATUS_OPTIONS:
        if status.lower() == normalized:
            return status
    return value.strip()


def normalize_role_name(value):
    for role in ROLE_OPTIONS:
        if role.lower() == value.strip().lower():
            return role
    return value.strip()


def parse_import_workbook(file_storage, update_empty_fields):
    workbook = load_workbook(file_storage, data_only=True)
    sheet = workbook.active
    header_row = None
    headers = {}
    for row_number in range(1, min(sheet.max_row, 10) + 1):
        row_values = [cell_text(sheet.cell(row=row_number, column=column).value) for column in range(1, sheet.max_column + 1)]
        if "Status" in row_values and "Full name" in row_values:
            header_row = row_number
            headers = {value: index + 1 for index, value in enumerate(row_values) if value}
            break

    if not header_row:
        raise ValueError("Could not find a valid header row.")

    missing_headers = sorted(IMPORT_REQUIRED_HEADERS - set(headers))
    if missing_headers:
        raise ValueError(f"Missing required columns: {', '.join(missing_headers)}.")

    unknown_headers = sorted(set(headers) - IMPORT_HEADERS)
    preview_rows = []
    seen_emails = set()
    existing_members = {
        member.email.lower(): member
        for member in AcademicStaff.query.filter(AcademicStaff.email.isnot(None)).all()
        if member.email
    }

    for row_number in range(header_row + 1, sheet.max_row + 1):
        row_data = {
            header: cell_text(sheet.cell(row=row_number, column=column).value)
            for header, column in headers.items()
            if header in IMPORT_HEADERS
        }
        if not any(row_data.values()):
            continue

        errors = []
        for header in IMPORT_REQUIRED_HEADERS:
            if not row_data.get(header, "").strip():
                errors.append(f"{header} is required.")

        status = normalize_status(row_data.get("Status", ""))
        if status and status not in IMPORT_STATUS_OPTIONS:
            errors.append("Status must be Active, Inactive or Archived.")
        row_data["Status"] = status

        roles = [normalize_role_name(role) for role in normalize_roles(row_data.get("Roles", ""))]
        invalid_roles = [role for role in roles if role not in ROLE_OPTIONS]
        if invalid_roles:
            errors.append(f"Invalid role(s): {', '.join(invalid_roles)}.")
        row_data["Roles"] = ", ".join(roles)

        email = row_data.get("Email", "").strip().lower()
        if email and not EMAIL_RE.match(email):
            errors.append("Email must be valid.")
        if email in seen_emails:
            errors.append("Duplicate email in import file.")
        if email:
            seen_emails.add(email)
        row_data["Email"] = email

        has_car = normalize_yes_no(row_data.get("Has a car", ""))
        if has_car and has_car not in IMPORT_HAS_CAR_OPTIONS:
            errors.append("Has a car must be Yes or No.")
        row_data["Has a car"] = has_car

        for url_header in ("CV", "Location point", "Profile picture"):
            if row_data.get(url_header) and not is_valid_url(row_data[url_header]):
                errors.append(f"{url_header} must be a valid URL.")

        seniority = normalize_yes_no(row_data.get("Seniority", ""))
        if seniority and seniority not in {"Yes", "No"}:
            errors.append("Seniority must be Yes or No if provided.")
        row_data["Seniority"] = seniority

        action = "Update" if email in existing_members else "Create"
        if errors:
            action = "Error"
        preview_rows.append(
            {
                "row_number": row_number,
                "full_name": row_data.get("Full name", ""),
                "email": email,
                "action": action,
                "errors": errors,
                "data": row_data,
            }
        )

    ready_rows = [row for row in preview_rows if row["action"] != "Error"]
    payload = {
        "created_on": datetime.now(timezone.utc).isoformat(),
        "update_empty_fields": update_empty_fields,
        "unknown_headers": unknown_headers,
        "rows": preview_rows,
        "summary": {
            "total": len(preview_rows),
            "create": sum(1 for row in preview_rows if row["action"] == "Create"),
            "update": sum(1 for row in preview_rows if row["action"] == "Update"),
            "errors": sum(1 for row in preview_rows if row["action"] == "Error"),
            "ready": len(ready_rows),
        },
    }
    return payload


def save_import_batch(payload):
    token = secrets.token_urlsafe(24)
    with open(import_batch_path(token), "w", encoding="utf-8") as file:
        json.dump(payload, file)
    return token


def load_import_batch(token):
    path = import_batch_path(token)
    if not token or not os.path.exists(path):
        return None
    with open(path, "r", encoding="utf-8") as file:
        return json.load(file)


def apply_import_row(member, row_data, update_empty_fields):
    mapping = {
        "Status": "status",
        "Title": "title",
        "Full name": "full_name",
        "Roles": "roles",
        "Phone": "phone",
        "Email": "email",
        "Has a car": "has_car",
        "Full address": "full_address_google_maps",
        "Street name": "street_name",
        "Street number": "street_number",
        "City": "city",
        "Postcode": "postcode",
        "Province": "province",
        "Country": "country",
        "Location point": "location_point",
        "CV": "cv",
        "History": "interview",
        "Account ID": "account_id",
        "Account owner": "account_owner",
        "Profile picture": "profile_picture",
        "Dietary requirements": "dietary_requirements",
        "Started in": "started_in",
    }
    for header, attr in mapping.items():
        value = row_data.get(header, "")
        if value or update_empty_fields or not member.id:
            setattr(member, attr, value)
    seniority = row_data.get("Seniority", "")
    if seniority or update_empty_fields or not member.id:
        member.seniority = seniority == "Yes"

def display_date(value):
    if not value:
        return ""
    try:
        parsed = datetime.strptime(value, "%Y-%m-%d")
    except ValueError:
        return value
    return parsed.strftime("%d/%m/%Y")


def display_session_date(value):
    if not value:
        return ""
    return value.strftime("%d/%m/%Y")


@staff_bp.app_template_filter("session_date")
def session_date_filter(value):
    return display_session_date(value)


@staff_bp.app_template_filter("long_session_date")
def long_session_date_filter(value):
    if not value:
        return ""
    return f"{value.strftime('%A')} {value.day}, {value.strftime('%B')} {value.year}"


def potential_preassigned_exam_session_date(value):
    if not value:
        return ""
    return f"{value.strftime('%A')} {value.day} {value.strftime('%B')} {value.year}"


def potential_preassigned_exam_session_label(session_record):
    date_label = potential_preassigned_exam_session_date(session_record.session_date)
    format_label = (session_record.format or "").strip()
    if format_label == "Onsite":
        location_parts = [part for part in [(session_record.city or "").strip(), (session_record.province or "").strip()] if part]
        location = ", ".join(location_parts)
        suffix = f"Onsite in {location}" if location else "Onsite"
    else:
        suffix = format_label or "-"
    return f"{session_record.exam_session_name} - {date_label} ({suffix})"


def potential_preassigned_exam_session_option(session_record):
    date_label = potential_preassigned_exam_session_date(session_record.session_date)
    format_label = (session_record.format or "").strip()
    if format_label == "Onsite":
        location_parts = [part for part in [(session_record.city or "").strip(), (session_record.province or "").strip()] if part]
        location = ", ".join(location_parts)
        meta_suffix = f"Onsite in {location}" if location else "Onsite"
    else:
        meta_suffix = format_label or "-"
    chip_date = session_record.session_date.strftime("%d %b %Y") if session_record.session_date else ""
    return {
        "id": session_record.id,
        "name": session_record.exam_session_name,
        "year": session_record.session_date.year if session_record.session_date else None,
        "meta": f"{date_label} · {meta_suffix}",
        "chip_label": f"{session_record.exam_session_name} · {chip_date}",
        "label": potential_preassigned_exam_session_label(session_record),
    }


def latest_potential_preassignable_exam_sessions():
    latest_year_record = (
        ExamSessionYear.query.filter_by(is_archived=False)
        .order_by(ExamSessionYear.year.desc())
        .first()
    )
    if latest_year_record is None:
        return []
    latest_year = latest_year_record.year
    return (
        ExamSession.query.filter(db.extract("year", ExamSession.session_date) == latest_year)
        .order_by(ExamSession.session_date.asc(), ExamSession.exam_session_name.asc(), ExamSession.id.asc())
        .all()
    )


def potential_preassigned_exam_session_options():
    return [
        potential_preassigned_exam_session_option(session_record)
        for session_record in latest_potential_preassignable_exam_sessions()
    ]


def potential_preassigned_exam_sessions_by_entry(entries, available_options=None):
    entry_ids = [entry.id for entry in entries if entry.id]
    if not entry_ids:
        return {}
    available_options = available_options if available_options is not None else potential_preassigned_exam_session_options()
    available_by_id = {option["id"]: option for option in available_options}
    links = (
        PotentialEntryPreassignedExamSession.query.filter(
            PotentialEntryPreassignedExamSession.potential_entry_id.in_(entry_ids)
        )
        .order_by(PotentialEntryPreassignedExamSession.created_on.asc(), PotentialEntryPreassignedExamSession.id.asc())
        .all()
    )
    session_ids = sorted({link.exam_session_id for link in links if link.exam_session_id not in available_by_id})
    session_options = dict(available_by_id)
    if session_ids:
        for session_record in ExamSession.query.filter(ExamSession.id.in_(session_ids)).all():
            session_options[session_record.id] = potential_preassigned_exam_session_option(session_record)

    selections = {entry_id: [] for entry_id in entry_ids}
    for link in links:
        option = session_options.get(link.exam_session_id)
        label = option["label"] if option else "Session no longer available"
        selections.setdefault(link.potential_entry_id, []).append({
            "id": link.exam_session_id,
            "name": option["name"] if option else "Session no longer available",
            "year": option["year"] if option else None,
            "label": label,
            "chip_label": option["chip_label"] if option else "Session no longer available",
            "available": option is not None,
        })
    return selections


def potential_entry_preassigned_email_sessions(entry):
    if not entry or not entry.id:
        return []
    links = PotentialEntryPreassignedExamSession.query.filter_by(potential_entry_id=entry.id).all()
    session_ids = [link.exam_session_id for link in links]
    if not session_ids:
        return []
    sessions_by_id = {
        session_record.id: session_record
        for session_record in ExamSession.query.filter(ExamSession.id.in_(session_ids)).all()
    }
    sessions = [sessions_by_id[session_id] for session_id in session_ids if session_id in sessions_by_id]
    sessions.sort(key=lambda session_record: (session_record.session_date, session_record.exam_session_name.lower(), session_record.id))
    payload = []
    for session_record in sessions:
        format_label = (session_record.format or "").strip()
        address = (session_record.full_address_google_maps or "").strip() if format_label == "Onsite" else ""
        payload.append({
            "name": session_record.exam_session_name or "",
            "date": potential_preassigned_exam_session_date(session_record.session_date),
            "format": format_label,
            "address": address,
        })
    return payload


def potential_entry_certification_email_programmes(entry):
    if not entry or not entry.id:
        return {"roles": [], "programmes": []}
    roles = [role for role in entry.roles_list() if role in {"Examiner", "Supervisor"}]
    programmes = []
    module_by_role = {
        "Examiner": EXAMINER_CERTIFICATION_MODULE_KEY,
        "Supervisor": SUPERVISOR_CERTIFICATION_MODULE_KEY,
    }
    year_by_role = {
        "Examiner": latest_active_examiner_certification_year,
        "Supervisor": latest_active_supervisor_certification_year,
    }
    for role in ["Examiner", "Supervisor"]:
        if role not in roles:
            continue
        selected_year = year_by_role[role]()
        config = certification_year_configuration(module_by_role[role], selected_year)
        remote_training = ""
        annual_meeting = ""
        if config and config.remote_training_start_date and config.remote_training_end_date:
            remote_training = (
                "from "
                f"{potential_preassigned_exam_session_date(config.remote_training_start_date)} "
                f"to {potential_preassigned_exam_session_date(config.remote_training_end_date)}"
            )
        if config and config.annual_meeting_date and config.annual_meeting_time and date_is_today_or_future(config.annual_meeting_date):
            start_hour = config.annual_meeting_time.strftime("%H:%M").lstrip("0")
            if start_hour.endswith(":00"):
                start_hour = start_hour[:-3]
            annual_meeting = (
                f"{potential_preassigned_exam_session_date(config.annual_meeting_date)} "
                f"from {start_hour} to 16 h (GMT-3)"
            )
        programmes.append({
            "role": role,
            "remote_training_period": remote_training,
            "annual_meeting": annual_meeting,
        })
    return {"roles": roles, "programmes": programmes}


def selected_potential_preassigned_exam_session_ids(form):
    selected_ids = []
    seen = set()
    for raw_id in form.getlist("preassigned_exam_session_ids"):
        try:
            session_id = int(raw_id)
        except (TypeError, ValueError):
            continue
        if session_id <= 0 or session_id in seen:
            continue
        seen.add(session_id)
        selected_ids.append(session_id)
    return selected_ids


def sync_potential_preassigned_exam_sessions(entry, form):
    selected_ids = selected_potential_preassigned_exam_session_ids(form)
    existing_links = {
        link.exam_session_id: link
        for link in PotentialEntryPreassignedExamSession.query.filter_by(potential_entry_id=entry.id).all()
    }
    for session_id in selected_ids:
        if session_id not in existing_links:
            db.session.add(PotentialEntryPreassignedExamSession(potential_entry_id=entry.id, exam_session_id=session_id))
        else:
            existing_links[session_id].updated_on = datetime.now(timezone.utc)
    for session_id, link in existing_links.items():
        if session_id not in selected_ids:
            db.session.delete(link)


def display_interviewer(value):
    if not value:
        return ""
    raw = str(value).strip()
    name = raw.split("|", 1)[0].strip()
    for option in INTERVIEWER_OPTIONS:
        if name.casefold() == option.casefold():
            return option
    return name


def display_time(value):
    raw = str(value or "").strip()
    match = re.fullmatch(r"(\d{2}:\d{2})(?::\d{2})?", raw)
    return match.group(1) if match else raw


def normalize_whatsapp_phone(value):
    return re.sub(r"\D+", "", str(value or ""))


@staff_bp.app_template_filter("whatsapp_phone")
def whatsapp_phone_filter(value):
    return normalize_whatsapp_phone(value)


