def certification_date_value(value):
    return value.strftime("%d/%m/%Y") if value else ""


def certification_time_value(value):
    return value.strftime("%H:%M") if value else ""


def today_local():
    return datetime.now(LOCAL_TZ).date()


def date_is_today_or_future(value):
    return bool(value and value >= today_local())


def certification_remote_training_period_value(config):
    if not config or not config.remote_training_start_date or not config.remote_training_end_date:
        return ""
    if config.remote_training_end_date < today_local():
        return ""
    return f"{certification_date_value(config.remote_training_start_date)} to {certification_date_value(config.remote_training_end_date)}"


def parse_dd_mm_yyyy_date(value, field_label):
    raw_value = (value or "").strip()
    if not raw_value:
        return None, None
    if not re.match(r"^\d{2}/\d{2}/\d{4}$", raw_value):
        return None, f"{field_label} must use DD/MM/YYYY."
    day = int(raw_value[:2])
    month = int(raw_value[3:5])
    year = int(raw_value[6:])
    if day < 1 or day > 31:
        return None, "Day must be between 01 and 31."
    if month < 1 or month > 12:
        return None, "Month must be between 01 and 12."
    if year < today_local().year:
        return None, "Year must be the current year or later."
    try:
        parsed = datetime.strptime(raw_value, "%d/%m/%Y").date()
    except ValueError:
        return None, "Please enter a valid date."
    return parsed, None


def parse_certification_date(value, selected_year, field_label):
    parsed, error = parse_dd_mm_yyyy_date(value, field_label)
    if error or parsed is None:
        return parsed, error
    if parsed.year != selected_year:
        return None, f"{field_label} must be in {selected_year}."
    if parsed < today_local():
        return None, "Date cannot be in the past."
    return parsed, None


def parse_certification_time(value, field_label):
    raw_value = (value or "").strip()
    if not raw_value:
        return None, None
    match = re.match(r"^(\d{2}):(\d{2})$", raw_value)
    if not match:
        return None, f"{field_label} must use hh:mm."
    hours = int(match.group(1))
    minutes = int(match.group(2))
    if hours < 0 or hours > 23:
        return None, f"{field_label} hour must be between 00 and 23."
    if minutes < 0 or minutes > 59:
        return None, f"{field_label} minutes must be between 00 and 59."
    try:
        parsed = datetime.strptime(raw_value, "%H:%M").time()
    except ValueError:
        return None, f"{field_label} must be a valid 24h time."
    return parsed, None


def parse_staff_settings_date(value, field_label):
    parsed, error = parse_dd_mm_yyyy_date(value, field_label)
    if error or parsed is None:
        return parsed, error
    if parsed < today_local():
        return None, "Date cannot be in the past."
    return parsed, None


def staff_members_settings():
    return StaffMembersSettings.query.order_by(StaffMembersSettings.id.asc()).first()


MAX_INDUCTION_SESSION_OPTIONS = 10


def induction_session_option_from_values(induction_date, start_time, end_time):
    return {
        "date": certification_date_value(induction_date),
        "start_time": certification_time_value(start_time),
        "end_time": certification_time_value(end_time),
    }


def induction_option_is_today_or_future(option):
    parsed, error = parse_dd_mm_yyyy_date(option.get("date"), "Upcoming induction session date")
    return bool(parsed and not error and parsed >= today_local())


def staff_members_induction_session_options(settings_record):
    if not settings_record:
        return []
    raw_options = (settings_record.upcoming_induction_session_options or "").strip()
    if raw_options:
        try:
            parsed_options = json.loads(raw_options)
        except json.JSONDecodeError:
            parsed_options = []
        options = []
        if isinstance(parsed_options, list):
            for option in parsed_options[:MAX_INDUCTION_SESSION_OPTIONS]:
                if not isinstance(option, dict):
                    continue
                options.append(
                    {
                        "date": (option.get("date") or "").strip(),
                        "start_time": (option.get("start_time") or "").strip(),
                        "end_time": (option.get("end_time") or "").strip(),
                    }
                )
        options = [option for option in options if induction_option_is_today_or_future(option)]
        if options:
            return options
    if (
        settings_record.upcoming_induction_session_date
        and settings_record.upcoming_induction_session_start_time
        and settings_record.upcoming_induction_session_end_time
        and date_is_today_or_future(settings_record.upcoming_induction_session_date)
    ):
        return [
            induction_session_option_from_values(
                settings_record.upcoming_induction_session_date,
                settings_record.upcoming_induction_session_start_time,
                settings_record.upcoming_induction_session_end_time,
            )
        ]
    return []


def certification_config_annual_meeting_values(config):
    if not config or not config.annual_meeting_date or not date_is_today_or_future(config.annual_meeting_date):
        return "", ""
    return certification_date_value(config.annual_meeting_date), certification_time_value(config.annual_meeting_time)


def staff_members_settings_values(settings_record):
    induction_options = staff_members_induction_session_options(settings_record)
    first_option = induction_options[0] if induction_options else {"date": "", "start_time": "", "end_time": ""}
    return {
        "upcoming_induction_session_date": first_option["date"],
        "upcoming_induction_session_start_time": first_option["start_time"],
        "upcoming_induction_session_end_time": first_option["end_time"],
        "upcoming_induction_session_options": induction_options or [{"date": "", "start_time": "", "end_time": ""}],
    }


def save_staff_members_settings():
    raw_dates = request.form.getlist("upcoming_induction_session_date")
    raw_start_times = request.form.getlist("upcoming_induction_session_start_time")
    raw_end_times = request.form.getlist("upcoming_induction_session_end_time")
    option_count = max(len(raw_dates), len(raw_start_times), len(raw_end_times), 1)
    if option_count > MAX_INDUCTION_SESSION_OPTIONS:
        flash("A maximum of 10 induction session date and time options can be saved.", "error")
        return False

    induction_options = []
    parsed_options = []
    for index in range(option_count):
        induction_date, date_error = parse_staff_settings_date(
            raw_dates[index] if index < len(raw_dates) else "",
            f"Upcoming induction session option {index + 1} date",
        )
        if date_error:
            flash(date_error, "error")
            return False
        start_time, start_error = parse_certification_time(
            raw_start_times[index] if index < len(raw_start_times) else "",
            f"Upcoming induction session option {index + 1} start time",
        )
        if start_error:
            flash(start_error, "error")
            return False
        end_time, end_error = parse_certification_time(
            raw_end_times[index] if index < len(raw_end_times) else "",
            f"Upcoming induction session option {index + 1} end time",
        )
        if end_error:
            flash(end_error, "error")
            return False
        values = [induction_date, start_time, end_time]
        if all(value is None for value in values):
            continue
        if any(value is None for value in values):
            flash("Please complete a valid date and time range for each induction session option.", "error")
            return False
        if start_time >= end_time:
            flash("Please complete a valid date and time range for each induction session option.", "error")
            return False
        induction_options.append(induction_session_option_from_values(induction_date, start_time, end_time))
        parsed_options.append((induction_date, start_time, end_time))

    settings_record = staff_members_settings()
    if settings_record is None:
        settings_record = StaffMembersSettings()
        db.session.add(settings_record)
    first_parsed_option = parsed_options[0] if parsed_options else (None, None, None)
    settings_record.upcoming_induction_session_date = first_parsed_option[0]
    settings_record.upcoming_induction_session_start_time = first_parsed_option[1]
    settings_record.upcoming_induction_session_end_time = first_parsed_option[2]
    settings_record.upcoming_induction_session_options = json.dumps(induction_options)
    db.session.commit()
    flash("Upcoming induction session date and time options updated.", "success")
    return True


def parse_certification_remote_training_period(value, selected_year):
    raw_value = (value or "").strip()
    if not raw_value:
        return None, None, None
    parts = [part.strip() for part in raw_value.split(" to ")]
    if len(parts) != 2:
        return None, None, "Remote training period must use DD/MM/YYYY to DD/MM/YYYY."
    start_date, start_error = parse_certification_date(parts[0], selected_year, "Remote training period start date")
    if start_error:
        return None, None, start_error
    end_date, end_error = parse_certification_date(parts[1], selected_year, "Remote training period end date")
    if end_error:
        return None, None, end_error
    if start_date < today_local() or end_date < today_local():
        return None, None, "Date cannot be in the past."
    if start_date >= end_date:
        return None, None, "Remote training period start date must be earlier than the end date."
    return start_date, end_date, None


def certification_year_configuration(module_key, selected_year):
    return CertificationYearConfiguration.query.filter_by(module_key=module_key, year=selected_year).first()


def save_certification_year_configuration(module_key, selected_year):
    annual_date, annual_error = parse_certification_date(
        request.form.get("annual_meeting_date", ""),
        selected_year,
        "Annual meeting date",
    )
    if annual_error:
        flash(annual_error, "error")
        return False
    annual_time, annual_time_error = parse_certification_time(
        request.form.get("annual_meeting_time", ""),
        "Annual meeting time",
    )
    if annual_time_error:
        flash(annual_time_error, "error")
        return False
    if annual_date is None:
        annual_time = None
    remote_start, remote_end, remote_error = parse_certification_remote_training_period(
        request.form.get("remote_training_period", ""),
        selected_year,
    )
    if remote_error:
        flash(remote_error, "error")
        return False
    config = certification_year_configuration(module_key, selected_year)
    if config is None:
        config = CertificationYearConfiguration(module_key=module_key, year=selected_year)
        db.session.add(config)
    config.annual_meeting_date = annual_date
    config.annual_meeting_time = annual_time
    config.remote_training_start_date = remote_start
    config.remote_training_end_date = remote_end
    db.session.commit()
    flash("Certification year settings saved successfully.", "success")
    return True


def latest_active_intern_stage_year():
    active_years = active_intern_stage_years()
    return active_years[-1].year


def active_intern_stage_years():
    years = (
        InternStageYear.query.filter_by(is_archived=False)
        .order_by(InternStageYear.year.asc())
        .all()
    )
    if not years:
        existing_years = [
            item.year for item in InternStageYear.query.order_by(InternStageYear.year.asc()).all()
        ]
        default_year = InternStageYear(
            year=(max(existing_years) + 1) if existing_years else 2026,
            is_archived=False,
        )
        db.session.add(default_year)
        db.session.commit()
        years = [default_year]
    return years


def selected_intern_stage_year():
    active_years = active_intern_stage_years()
    requested_year = request.args.get("certification_year", "").strip()
    if not requested_year:
        requested_year = request.form.get("certification_year", "").strip()
    if not requested_year:
        return_to = request.form.get("return_to", "").strip()
        if return_to:
            requested_year = parse_qs(urlparse(return_to).query).get("certification_year", [""])[0]
    if requested_year.isdigit():
        year_number = int(requested_year)
        if any(item.year == year_number for item in active_years):
            return year_number, active_years
    return active_years[-1].year, active_years


def active_exam_session_years():
    years = (
        ExamSessionYear.query.filter_by(is_archived=False)
        .order_by(ExamSessionYear.year.asc())
        .all()
    )
    if not years:
        existing_years = [
            item.year for item in ExamSessionYear.query.order_by(ExamSessionYear.year.asc()).all()
        ]
        default_year = ExamSessionYear(
            year=(max(existing_years) + 1) if existing_years else 2026,
            is_archived=False,
        )
        db.session.add(default_year)
        db.session.commit()
