def exam_session_year_redirect(year=None):
    endpoint = request.form.get("return_to_endpoint", "").strip()
    if endpoint in {"staff.exam_session_planner", "staff.monthly_exam_session_registrations", "staff.pre_session_control_tower"}:
        return redirect(url_for(endpoint, session_year=year) if year else url_for(endpoint))
    return_to = request.form.get("return_to", "").strip()
    if return_to.startswith(url_for("staff.monthly_exam_session_registrations")):
        return redirect(return_to)
    return redirect(url_for("staff.exam_session_planner", session_year=year) if year else url_for("staff.exam_session_planner"))


def schedule_workflow_status(workflow):
    return workflow.status if workflow else "Not started"


def schedule_workflow_next_action(status):
    return SCHEDULE_WORKFLOW_NEXT_ACTIONS.get(status, "")


def schedule_workflow_responsible(status):
    return SCHEDULE_WORKFLOW_RESPONSIBLE.get(status, "")


def schedule_workflow_review_round(workflow):
    return workflow.review_round if workflow else 0


def schedule_workflow_current_deadline(workflow):
    return workflow.next_action_due_at if workflow else None


def local_date(value):
    if not value:
        return None
    if isinstance(value, datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        return value.astimezone(LOCAL_TZ).date()
    return value


def schedule_workflow_latest_recorded_deadline(workflow):
    if not workflow:
        return None
    if workflow.next_action_due_at:
        return workflow.next_action_due_at
    events = sorted(
        (event for event in workflow.events if event.due_at),
        key=lambda event: (event.created_at or datetime.min.replace(tzinfo=timezone.utc), event.id or 0),
        reverse=True,
    )
    return events[0].due_at if events else None


def schedule_workflow_completed_date(workflow):
    if not workflow:
        return None
    if workflow.approved_at:
        return local_date(workflow.approved_at)
    approved_events = sorted(
        (event for event in workflow.events if event.new_status == "Approved"),
        key=lambda event: (event.created_at or datetime.min.replace(tzinfo=timezone.utc), event.id or 0),
        reverse=True,
    )
    if approved_events:
        return local_date(approved_events[0].created_at)
    return local_date(workflow.updated_at)


def deadline_badge_contract(deadline, completed=False, completed_date=None, today=None):
    today = today or datetime.now(LOCAL_TZ).date()
    if not deadline:
        return None
    if completed:
        met_deadline = bool(completed_date and completed_date <= deadline)
        completed_label = completed_date.strftime("%d/%m/%Y") if completed_date else ""
        label = "Deadline met" if met_deadline else "Deadline not met"
        if completed_label:
            label = f"{label} on {completed_label}"
        return {
            "date": deadline,
            "status": "met" if met_deadline else "missed",
            "completed_date": completed_date,
            "label": label,
        }
    overdue = deadline < today
    return {
        "date": deadline,
        "status": "overdue" if overdue else "on-track",
        "label": "Deadline overdue" if overdue else "Deadline on track",
    }


def schedule_deadline_badge_contract(workflow, status=None, today=None):
    status = status or schedule_workflow_status(workflow)
    deadline = schedule_workflow_latest_recorded_deadline(workflow) if status == "Approved" else schedule_workflow_current_deadline(workflow)
    return deadline_badge_contract(
        deadline,
        completed=status == "Approved",
        completed_date=schedule_workflow_completed_date(workflow) if status == "Approved" else None,
        today=today,
    )


def schedule_workflow_health(status, deadline, today=None):
    if status == "Approved":
        return "Completed"
    if today is None:
        today = datetime.now(LOCAL_TZ).date()
    if not deadline:
        return "Deadline missing"
    if deadline < today:
        return "Overdue"
    return "On track"


def schedule_gate_status(workflow):
    status = schedule_workflow_status(workflow)
    is_ready = status == "Approved"
    if is_ready:
        return {
            "status": "ready",
            "label": "Ready",
            "message": "Schedules are approved. The session can move to the next pre-session stages.",
            "is_ready": True,
        }
    return {
        "status": "blocked",
        "label": "Blocked",
        "message": "This session cannot move to the next pre-session stages until the schedules are approved.",
        "is_ready": False,
    }


def pluralize_phrase(count, singular, plural=None):
    return f"{count} {singular if count == 1 else (plural or f'{singular}s')}"


def staffing_contract_status_label(status):
    return {
        "not_configured": "Not configured",
        "open_positions": "Open positions",
        "awaiting_confirmations": "Awaiting confirmations",
        "confirmed": "Ready",
        "invalid": "Needs review",
    }.get(status, "Needs review")


def staffing_contract_blocker_messages(contract):
    totals = contract.get("totals", {})
    status = contract.get("status")
    if status == "not_configured":
        return ["Staff roles have not been configured for this session."]
    if status == "invalid":
        return ["Staffing data needs to be reviewed before the session can be considered ready."]
    messages = []
    open_positions = totals.get("open_positions", 0)
    pending_confirmations = totals.get("pending_assigned", 0)
    sent_confirmations = totals.get("sent", 0)
    if open_positions:
        for detail in contract.get("open_position_details", []):
            role = detail.get("role") or "Staff"
            messages.append(f"1 {role} position still needs to be filled.")
        if not messages:
            messages.append(f"{pluralize_phrase(open_positions, 'staff position')} still need to be filled.")
    if pending_confirmations:
        messages.append(f"{pluralize_phrase(pending_confirmations, 'confirmation')} to be sent.")
    if sent_confirmations:
        messages.append(f"{pluralize_phrase(sent_confirmations, 'confirmation')} to be updated.")
    return messages


def staffing_presentation_from_contract(contract):
    totals = contract.get("totals", empty_staffing_counts())
    required = totals.get("required", 0)
    confirmed = totals.get("confirmed", 0)
    open_positions = totals.get("open_positions", 0)
    pending_confirmations = totals.get("pending_assigned", 0)
    sent_confirmations = totals.get("sent", 0)
    awaiting = pending_confirmations + sent_confirmations
    status = contract.get("status", "not_configured")
    role_rows = []
    for role in ("Emergency contact", "Supervisor", "Examiner", "Intern"):
        counts = contract.get("by_role", {}).get(role, empty_staffing_counts())
        if counts.get("required", 0) == 0:
            continue
        role_rows.append({
            "role": role,
            "required": counts.get("required", 0),
            "assigned": counts.get("assigned", 0),
            "pending": counts.get("pending_assigned", 0),
            "sent": counts.get("sent", 0),
            "confirmed": counts.get("confirmed", 0),
            "open": counts.get("open_positions", 0),
        })
    secondary_lines = []
    if open_positions:
        secondary_lines.append(f"{pluralize_phrase(open_positions, 'role')} to cover")
    if pending_confirmations:
        secondary_lines.append(f"{pluralize_phrase(pending_confirmations, 'confirmation')} to be sent")
    if sent_confirmations:
        secondary_lines.append(f"{pluralize_phrase(sent_confirmations, 'confirmation')} to be updated")
    if required == 0:
        summary = "Staffing has not been configured for this session."
        table_summary = "No staff roles configured"
    else:
        summary = f"{confirmed} of {required} required positions are confirmed."
        table_summary = f"{confirmed} / {required} confirmed"
    tooltip_lines = []
    for row in role_rows:
        parts = [
            f"{row['required']} required",
            f"{row['confirmed']} confirmed",
        ]
        if row["open"]:
            parts.append(f"{row['open']} open")
        if row["pending"]:
            parts.append(f"{row['pending']} pending")
        if row["sent"]:
            parts.append(f"{row['sent']} sent")
        tooltip_lines.append(f"{row['role']}: {' · '.join(parts)}")
    status_chips = []
    if open_positions:
        status_chips.append({
            "status": "roles-to-cover",
            "label": "Roles to cover",
            "recommended_action": "Verify open roles with Management",
        })
    if totals.get("pending_assigned", 0):
        status_chips.append({
            "status": "confirmations-to-be-sent",
            "label": "Confirmations to be sent",
            "recommended_action": "Send official confirmation emails",
        })
    if totals.get("sent", 0):
        status_chips.append({
            "status": "confirmations-to-be-updated",
            "label": "Confirmations to be updated",
            "recommended_action": "Follow up on confirmation email status",
        })
    if required > 0 and open_positions == 0 and confirmed == required:
        status_chips.append({
            "status": "confirmed-staff",
            "label": "Confirmed",
            "recommended_action": "Staffing completed",
        })
    if not status_chips:
        status_chips.append({
            "status": status.replace("_", "-"),
            "label": staffing_contract_status_label(status),
        })
    recommended_actions = [
        chip["recommended_action"]
        for chip in status_chips
        if chip.get("recommended_action") and chip.get("recommended_action") != "Staffing completed"
    ]
    return {
        "status": status,
        "label": staffing_contract_status_label(status),
        "status_chips": status_chips,
        "recommended_actions": recommended_actions,
        "summary": summary,
        "table_summary": table_summary,
        "secondary_lines": secondary_lines,
        "required": required,
        "assigned": totals.get("assigned", 0),
        "open_positions": open_positions,
        "pending": totals.get("pending_assigned", 0),
        "sent": totals.get("sent", 0),
        "confirmed": confirmed,
        "awaiting": awaiting,
        "role_rows": role_rows,
        "blockers": staffing_contract_blocker_messages(contract),
        "tooltip": "\n".join(tooltip_lines) if tooltip_lines else "Staffing has not been configured for this session.",
        "ready": contract.get("ready", False),
    }


def staffing_assignment_person(assignment):
    if not assignment:
        return None
    return assignment.team_member or assignment.potential_entry


def staffing_assignment_person_name(assignment):
    person = staffing_assignment_person(assignment)
    return (getattr(person, "full_name", "") or "").strip()


def staffing_assignment_person_email(assignment):
    person = staffing_assignment_person(assignment)
    return (getattr(person, "email", "") or "").strip()


def staffing_assignment_role_label(assignment_type, assignment=None):
    if assignment_type == "emergency_contact":
        return "Emergency contact"
    if assignment_type == "supervisor":
        if assignment is not None and getattr(assignment, "is_remote", False):
            return "Supervisor (remote)"
        return "Supervisor"
    if assignment_type == "examiner":
        return "Examiner"
    if assignment_type == "intern":
        return "Intern"
    return "Staff"


def record_staffing_status_change(session_record, assignment, assignment_type, previous_status, new_status, note=None):
    previous_label = staffing_participation_status_label(previous_status)
    new_label = staffing_participation_status_label(new_status)
    if previous_label == new_label:
        return None
    event = ExamSessionStaffingEvent(
        exam_session_id=session_record.id,
        assignment_type=assignment_type,
        assignment_id=assignment.id,
        role=staffing_assignment_role_label(assignment_type, assignment),
        staff_member_name=staffing_assignment_person_name(assignment) or "Role to cover",
        previous_status=previous_label,
        new_status=new_label,
        note=(note or "").strip() or None,
        created_by=session.get("user") if has_request_context() else None,
    )
    db.session.add(event)
    return event


def staffing_participation_status_label(status):
    return LEGACY_PARTICIPATION_STATUS_MAP.get(status, status or "Pending")


def staffing_participation_status_class(status):
    return staffing_participation_status_label(status).lower().replace(" ", "-")


def staffing_assignment_has_staff_member(assignment):
    return bool(
        getattr(assignment, "team_member_id", None)
        or getattr(assignment, "potential_entry_id", None)
        or staffing_assignment_person_name(assignment)
    )


def staffing_deadline_start_date(value=None):
    if isinstance(value, datetime):
        return value.astimezone(LOCAL_TZ).date()
    if isinstance(value, date):
        return value
    return datetime.now(LOCAL_TZ).date()


def staffing_assignment_deadline_label(due_at, status="Pending", today=None):
    clean_status = staffing_participation_status_label(status)
    if clean_status in {"Confirmed", "Declined", "Cancelled", "Assigned"}:
        return "Completed"
    if not due_at:
        return "-"
    if today is None:
        today = datetime.now(LOCAL_TZ).date()
    if due_at < today:
        return "Overdue"
    if due_at == today:
        return "Due today"
    return due_at.strftime("%d/%m/%Y")


def staffing_assignment_deadline_status(due_at, status="Pending", today=None):
    clean_status = staffing_participation_status_label(status)
    if clean_status in {"Confirmed", "Declined", "Cancelled", "Assigned"}:
        return "completed"
    if not due_at:
        return "not-set"
    if today is None:
        today = datetime.now(LOCAL_TZ).date()
    if due_at < today:
        return "overdue"
    if due_at == today:
        return "due-today"
    return "upcoming"


def set_staffing_assignment_deadline(assignment, business_days, start_at=None, stage=""):
    if not assignment:
        return False
    start_date = staffing_deadline_start_date(start_at)
    due_at = argentina_add_business_days(start_date, business_days)
    start_value = start_at if isinstance(start_at, datetime) else None
    if not start_value:
        start_value = datetime.now(timezone.utc)
    if (
        getattr(assignment, "staffing_status_due_at", None) != due_at
        or getattr(assignment, "staffing_status_due_stage", None) != stage
    ):
        assignment.staffing_status_due_at = due_at
        assignment.staffing_status_due_stage = stage or None
        assignment.staffing_status_due_started_at = start_value
        return True
    return False


def clear_staffing_assignment_deadline(assignment):
    if assignment and (
        getattr(assignment, "staffing_status_due_at", None) is not None
        or getattr(assignment, "staffing_status_due_stage", None) is not None
        or getattr(assignment, "staffing_status_due_started_at", None) is not None
    ):
        assignment.staffing_status_due_at = None
        assignment.staffing_status_due_stage = None
        assignment.staffing_status_due_started_at = None
        return True
    return False


def sync_staffing_assignment_deadlines_for_session(session_record, workflow=None, assignments=None, today=None):
    if not session_record:
        return False
    workflow = workflow or ExamSessionScheduleWorkflow.query.filter_by(exam_session_id=session_record.id).first()
    assignments = assignments if assignments is not None else (
        ExamSessionSupervisorAssignment.query.filter_by(exam_session_id=session_record.id).all()
        + ExamSessionExaminerAssignment.query.filter_by(exam_session_id=session_record.id).all()
        + ExamSessionInternAssignment.query.filter_by(exam_session_id=session_record.id).all()
    )
    schedule_unlocked = workflow and workflow.status == "Approved"
    changed = False
    for assignment in assignments:
        status = staffing_participation_status_label(getattr(assignment, "participation_status", "Pending"))
        if not schedule_unlocked or not staffing_assignment_has_staff_member(assignment):
            changed = clear_staffing_assignment_deadline(assignment) or changed
        elif status == "Pending":
            if getattr(assignment, "staffing_status_due_stage", None) != "Pending" or not getattr(assignment, "staffing_status_due_at", None):
                changed = set_staffing_assignment_deadline(
                    assignment,
                    2,
                    workflow.approved_at or today,
                    stage="Pending",
                ) or changed
        elif status == "Official confirmation sent":
            if (
                getattr(assignment, "staffing_status_due_stage", None) != "Official confirmation sent"
                or not getattr(assignment, "staffing_status_due_at", None)
            ):
                changed = set_staffing_assignment_deadline(
                    assignment,
                    3,
                    assignment.updated_on or today,
                    stage="Official confirmation sent",
                ) or changed
        elif status == "Confirmed":
            continue
        else:
            if status not in {"Pending", "Official confirmation sent"}:
                changed = clear_staffing_assignment_deadline(assignment) or changed
    emergency_status = staffing_participation_status_label(getattr(session_record, "emergency_contact_participation_status", "Pending"))
    if not schedule_unlocked or not getattr(session_record, "emergency_contact_member_id", None):
        if getattr(session_record, "emergency_contact_status_due_at", None):
            clear_emergency_contact_deadline(session_record)
            changed = True
    elif emergency_status == "Pending":
        if (
            getattr(session_record, "emergency_contact_status_due_stage", None) != "Pending"
            or not getattr(session_record, "emergency_contact_status_due_at", None)
        ):
            set_emergency_contact_deadline(
                session_record,
                2,
                workflow.approved_at or today,
                stage="Pending",
            )
            changed = True
    elif emergency_status == "Official confirmation sent":
        if (
            getattr(session_record, "emergency_contact_status_due_stage", None) != "Official confirmation sent"
            or not getattr(session_record, "emergency_contact_status_due_at", None)
        ):
            set_emergency_contact_deadline(
                session_record,
                3,
                getattr(session_record, "emergency_contact_status_due_started_at", None) or today,
                stage="Official confirmation sent",
            )
            changed = True
    elif emergency_status == "Confirmed":
        pass
    else:
        if getattr(session_record, "emergency_contact_status_due_at", None):
            clear_emergency_contact_deadline(session_record)
            changed = True
    return changed


def schedule_locked_by_staffing_assignments(session_record):
    if not session_record:
        return False
    assignments = (
        ExamSessionSupervisorAssignment.query.filter_by(exam_session_id=session_record.id).all()
        + ExamSessionExaminerAssignment.query.filter_by(exam_session_id=session_record.id).all()
        + ExamSessionInternAssignment.query.filter_by(exam_session_id=session_record.id).all()
    )
    return any(
        normalize_participation_status(getattr(assignment, "participation_status", "Pending")) != "Pending"
        for assignment in assignments
    )


def staffing_assignment_row(role, assignment=None, assignment_type="", status="Pending", staff_name="", staff_email="", receives_shipment=False, updatable=True, assignment_id=None, due_at=None):
    clean_status = staffing_participation_status_label(status)
    resolved_name = staff_name or staffing_assignment_person_name(assignment)
    has_staff_member = bool(
        resolved_name
        or getattr(assignment, "team_member_id", None)
        or getattr(assignment, "potential_entry_id", None)
    )
    return {
        "role": role,
        "assignment_type": assignment_type,
        "assignment_id": assignment_id if assignment_id is not None else (assignment.id if assignment else None),
        "staff_name": resolved_name or "Assigned staff member",
        "staff_email": staff_email or staffing_assignment_person_email(assignment),
        "status": clean_status,
        "status_class": staffing_participation_status_class(clean_status),
        "deadline": due_at if due_at is not None else getattr(assignment, "staffing_status_due_at", None),
        "deadline_label": staffing_assignment_deadline_label(due_at if due_at is not None else getattr(assignment, "staffing_status_due_at", None), clean_status),
        "deadline_status": staffing_assignment_deadline_status(due_at if due_at is not None else getattr(assignment, "staffing_status_due_at", None), clean_status),
        "receives_shipment": receives_shipment or bool(getattr(assignment, "is_shipment_recipient", False)),
        "has_staff_member": has_staff_member,
        "updatable": bool(updatable and (assignment_id is not None or (assignment and assignment.id))),
    }


def staffing_assignment_rows(session_record, supervisor_assignments=None, examiner_assignments=None, intern_assignments=None):
    rows = []
    if session_record and session_record.emergency_contact_member:
        rows.append(staffing_assignment_row(
            "Emergency contact",
            assignment_type="emergency_contact",
            assignment_id=session_record.id,
            status=session_record.emergency_contact_participation_status,
            staff_name=session_record.emergency_contact_member.full_name,
            staff_email=session_record.emergency_contact_member.email,
            due_at=session_record.emergency_contact_status_due_at,
        ))
    for assignment in supervisor_assignments or []:
        rows.append(staffing_assignment_row(
            "Supervisor (remote)" if assignment.is_remote else "Supervisor",
            assignment=assignment,
            assignment_type="supervisor",
            status=assignment.participation_status,
        ))
    for assignment in examiner_assignments or []:
        rows.append(staffing_assignment_row(
            "Examiner",
            assignment=assignment,
            assignment_type="examiner",
            status=assignment.participation_status,
        ))
    for assignment in intern_assignments or []:
        rows.append(staffing_assignment_row(
            "Intern",
            assignment=assignment,
            assignment_type="intern",
            status=assignment.participation_status,
        ))
    return rows


def staffing_control_contract(staffing_control=None, staffing_contract=None, today=None):
    if today is None:
        today = datetime.now(LOCAL_TZ).date()
    staffing_ready = bool((staffing_contract or {}).get("ready"))
    deadline = staffing_control.staffing_due_at if staffing_control else None
    note = (staffing_control.note or "").strip() if staffing_control and staffing_control.note else ""
    if staffing_ready:
        deadline_status = "completed"
        deadline_label = "Completed"
        is_overdue = False
    elif not deadline:
        deadline_status = "not_set"
        deadline_label = "Not set"
        is_overdue = False
    elif deadline < today:
        deadline_status = "overdue"
        deadline_label = "Overdue"
        is_overdue = True
    elif deadline == today:
        deadline_status = "due_today"
        deadline_label = "Due today"
        is_overdue = False
    else:
        deadline_status = "upcoming"
        deadline_label = ""
        is_overdue = False
    return {
        "department": "ADMIN",
        "responsible_user": None,
        "responsible_label": "ADMIN",
        "responsible_person_label": "Not assigned",
        "deadline": deadline,
        "deadline_label": deadline_label,
        "deadline_status": deadline_status,
        "note": note,
        "updated_by": staffing_control.updated_by if staffing_control else "",
        "is_overdue": is_overdue,
    }


def staffing_deadline_badge_contract(staffing_control=None, staffing_contract=None, assignments=None, staffing_events=None, session_record=None, today=None):
    deadline = staffing_control.staffing_due_at if staffing_control else None
    completed = bool((staffing_contract or {}).get("ready"))
    if not deadline:
        assignment_deadlines = []
        for assignment in assignments or []:
            due_at = getattr(assignment, "staffing_status_due_at", None)
            if not due_at:
                continue
            if completed or staffing_assignment_deadline_status(
                due_at,
                getattr(assignment, "participation_status", "Pending"),
                today=today,
            ) not in {"completed", "not-set"}:
                assignment_deadlines.append(due_at)
        if session_record and getattr(session_record, "emergency_contact_status_due_at", None):
            emergency_due_at = session_record.emergency_contact_status_due_at
            if completed or staffing_assignment_deadline_status(
                emergency_due_at,
                getattr(session_record, "emergency_contact_participation_status", "Pending"),
                today=today,
            ) not in {"completed", "not-set"}:
                assignment_deadlines.append(emergency_due_at)
        if completed and not assignment_deadlines:
            assignment_deadlines.extend(staffing_inferred_deadlines_from_events(
                staffing_events,
                assignments=assignments,
                session_record=session_record,
            ))
        deadline = min(assignment_deadlines) if assignment_deadlines else None
    completed_dates = []
    for event in staffing_events or []:
        if staffing_participation_status_label(event.new_status) == "Confirmed":
            event_date = local_date(event.created_at)
            if event_date:
                completed_dates.append(event_date)
    for assignment in assignments or []:
        if staffing_participation_status_label(getattr(assignment, "participation_status", "")) == "Confirmed":
            assignment_date = local_date(getattr(assignment, "updated_on", None) or getattr(assignment, "created_on", None))
            if assignment_date:
                completed_dates.append(assignment_date)
    if session_record and staffing_participation_status_label(getattr(session_record, "emergency_contact_participation_status", "")) == "Confirmed":
        emergency_date = local_date(getattr(session_record, "updated_on", None) or getattr(session_record, "created_on", None))
        if emergency_date:
            completed_dates.append(emergency_date)
    return deadline_badge_contract(
        deadline,
        completed=completed,
        completed_date=max(completed_dates) if completed_dates else None,
        today=today,
    )


def staffing_inferred_deadlines_from_events(staffing_events=None, assignments=None, session_record=None):
    confirmed_refs = {
        (assignment_type, assignment.id)
        for assignment_type, assignment_list in (
            ("supervisor", [assignment for assignment in assignments or [] if isinstance(assignment, ExamSessionSupervisorAssignment)]),
            ("examiner", [assignment for assignment in assignments or [] if isinstance(assignment, ExamSessionExaminerAssignment)]),
            ("intern", [assignment for assignment in assignments or [] if isinstance(assignment, ExamSessionInternAssignment)]),
        )
        for assignment in assignment_list
        if staffing_participation_status_label(getattr(assignment, "participation_status", "")) == "Confirmed"
    }
    if (
        session_record
        and staffing_participation_status_label(getattr(session_record, "emergency_contact_participation_status", "")) == "Confirmed"
    ):
        confirmed_refs.add(("emergency_contact", session_record.id))
    deadlines = []
    for event in sorted(staffing_events or [], key=lambda item: (item.created_at or datetime.min.replace(tzinfo=timezone.utc), item.id or 0), reverse=True):
        ref = (event.assignment_type, event.assignment_id)
        if ref not in confirmed_refs:
            continue
        if staffing_participation_status_label(event.new_status) != "Confirmed":
            continue
        previous_status = staffing_participation_status_label(event.previous_status)
        if previous_status == "Official confirmation sent":
            deadline_start = local_date(event.created_at)
            if deadline_start:
                deadlines.append(argentina_add_business_days(deadline_start, 3))
        elif previous_status == "Pending":
            deadline_start = local_date(event.created_at)
            if deadline_start:
                deadlines.append(argentina_add_business_days(deadline_start, 2))
    return deadlines


