def interview_history_entries(history):
    if not history:
        return []
    entries = []
    for index, block in enumerate(history.strip().split("\n\n")):
        lines = [line for line in block.splitlines() if line.strip()]
        if not lines:
            continue
        if len(lines) == 1:
            entries.append({
                "index": index,
                "date": "Legacy note",
                "note": lines[0],
                "note_id": "",
                "from_full_name": "",
                "from_department": "",
                "from_user_id": None,
                "to_full_name": "",
                "to_department": "",
                "to_user_id": None,
                "to_user_ids": [],
                "to_label": "",
                "to_labels": [],
            })
        else:
            metadata = {
                "note_id": "",
                "from_full_name": "",
                "from_department": "",
                "from_user_id": None,
                "to_full_name": "",
                "to_department": "",
                "to_user_id": None,
                "to_user_ids": [],
                "to_label": "",
                "to_labels": [],
            }
            note_lines = []
            for line in lines[1:]:
                if line.startswith("Note ID:"):
                    metadata["note_id"] = line.replace("Note ID:", "", 1).strip()
                    continue
                if line.startswith("From:"):
                    value = line.replace("From:", "", 1).strip()
                    if value != "-":
                        parts = [part.strip() for part in value.split(",", 1)]
                        metadata["from_full_name"] = parts[0] if parts else ""
                        metadata["from_department"] = parts[1] if len(parts) > 1 else ""
                    continue
                if line.startswith("From user ID:"):
                    value = line.replace("From user ID:", "", 1).strip()
                    if value.isdigit():
                        metadata["from_user_id"] = int(value)
                    continue
                if line.startswith("To:"):
                    value = line.replace("To:", "", 1).strip()
                    if value != "-":
                        labels = [part.strip() for part in value.split(";") if part.strip()]
                        metadata["to_label"] = value
                        metadata["to_labels"] = labels
                        parts = [part.strip() for part in labels[0].split(",", 1)] if labels else []
                        metadata["to_full_name"] = parts[0] if parts else ""
                        metadata["to_department"] = parts[1] if len(parts) > 1 else ""
                    continue
                if line.startswith("To user ID:"):
                    value = line.replace("To user ID:", "", 1).strip()
                    user_ids = []
                    for raw_user_id in value.split(","):
                        raw_user_id = raw_user_id.strip()
                        if raw_user_id.isdigit():
                            user_ids.append(int(raw_user_id))
                    metadata["to_user_ids"] = user_ids
                    metadata["to_user_id"] = user_ids[0] if user_ids else None
                    continue
                note_lines.append(line)
            entries.append({"index": index, "date": lines[0], "note": "\n".join(note_lines), **metadata})
    return entries


def delete_interview_history_entry(history, note_index):
    if not history:
        return history, ""
    blocks = [block for block in history.strip().split("\n\n") if block.strip()]
    if note_index < 0 or note_index >= len(blocks):
        return history, ""
    deleted_block = blocks[note_index]
    deleted_note_id = ""
    for line in deleted_block.splitlines():
        if line.startswith("Note ID:"):
            deleted_note_id = line.replace("Note ID:", "", 1).strip()
            break
    del blocks[note_index]
    return "\n\n".join(blocks), deleted_note_id


@staff_bp.app_template_filter("potential_cv_review_note_parts")
def potential_cv_review_note_parts_filter(value):
    text = value or ""
    match = re.match(r"^CV review - ([^:]+):\s*(.*)$", text, flags=re.S)
    if match:
        return {"department": match.group(1).strip(), "text": match.group(2).strip()}
    if text.startswith("CV review:"):
        return {"department": "", "text": text.replace("CV review:", "", 1).strip()}
    return {"department": "", "text": text}


def interview_history_count(history):
    return len(interview_history_entries(history))


def certification_status_sort_rank(status):
    return {"Pending": 0, "In progress": 1, "Certified": 2}.get(status or "", -1)


def remote_training_sort_rank(status):
    return {"Pending": 0, "With FUT": 1, "Certified": 2}.get(status or "", -1)


def annual_meeting_sort_rank(status):
    return {"Absent": 0, "Attended": 1, "Certified": 2}.get(status or "", -1)


def intern_stage_status_sort_rank(status):
    return {"Pending": 0, "In progress": 1, "Completed": 2}.get(status or "", -1)


def intern_stage_step_sort_rank(status):
    return {
        "Pending": 0,
        "Attended meeting": 1,
        "With FUT": 2,
        "Completed": 3,
        "Certified": 3,
    }.get(status or "", -1)


def sort_certification_members(
    members,
    sort_by,
    sort_dir,
    certification_statuses,
    annual_meeting_selections,
    remote_training_selections,
    fut_selections,
):
    if sort_by not in {"status", "full_name", "history", "annual_meeting", "remote_training", "fut"}:
        return members
    reverse = sort_dir == "desc"

    def sort_value(member):
        if sort_by == "status":
            return certification_status_sort_rank(certification_statuses.get(member.id))
        if sort_by == "full_name":
            return (member.full_name or "").casefold()
        if sort_by == "history":
            return interview_history_count(member.interview)
        if sort_by == "annual_meeting":
            selection = annual_meeting_selections.get(member.id)
            return annual_meeting_sort_rank(selection.status if selection else "Absent")
        if sort_by == "remote_training":
            selection = remote_training_selections.get(member.id)
            return remote_training_sort_rank(selection.status if selection else "Pending")
        if sort_by == "fut":
            return len(fut_selections.get(member.id, []))
        return ""

    name_sorted_members = sorted(members, key=lambda member: (member.full_name or "").casefold())
    return sorted(name_sorted_members, key=sort_value, reverse=reverse)


def sort_intern_stage_members(
    members,
    sort_by,
    sort_dir,
    certification_statuses,
    remote_training_selections,
    stage_2_selections,
    stage_3_selections,
    fut_selections,
):
    if sort_by not in {"status", "full_name", "history", "stage_1", "stage_2", "fut", "stage_3"}:
        return members
    reverse = sort_dir == "desc"

    def sort_value(member):
        if sort_by == "status":
            return intern_stage_status_sort_rank(certification_statuses.get(member.id))
        if sort_by == "full_name":
            return (member.full_name or "").casefold()
        if sort_by == "history":
            return interview_history_count(member.interview)
        if sort_by == "stage_1":
            selection = remote_training_selections.get(member.id)
            return intern_stage_step_sort_rank(selection.status if selection else "Pending")
        if sort_by == "stage_2":
            selection = stage_3_selections.get(member.id)
            return intern_stage_step_sort_rank(selection.status if selection else "Pending")
        if sort_by == "fut":
            return len(fut_selections.get(member.id, []))
        if sort_by == "stage_3":
            selection = stage_2_selections.get(member.id)
            return intern_stage_step_sort_rank(selection.status if selection else "Pending")
        return ""

    name_sorted_members = sorted(members, key=lambda member: (member.full_name or "").casefold())
    return sorted(name_sorted_members, key=sort_value, reverse=reverse)


