def replace_potential_entry_ref_values(raw_value, entry_id, member_id):
    token = f"potential:{entry_id}"
    try:
        values = json.loads(raw_value or "[]")
    except (TypeError, ValueError, json.JSONDecodeError):
        return raw_value
    changed = False
    updated_values = []
    for value in values:
        text = str(value).strip()
        if text == token:
            updated_values.append(str(member_id))
            changed = True
        else:
            updated_values.append(value)
    return json.dumps(updated_values) if changed else raw_value


def promote_potential_entry_exam_session_assignments(entry, member):
    for assignment_model in (ExamSessionSupervisorAssignment, ExamSessionExaminerAssignment, ExamSessionInternAssignment):
        for assignment in assignment_model.query.filter_by(potential_entry_id=entry.id).all():
            assignment.team_member_id = member.id
            assignment.potential_entry_id = None
        for assignment in assignment_model.query.filter(assignment_model.non_available_member_ids.like(f"%potential:{entry.id}%")).all():
            assignment.non_available_member_ids = replace_potential_entry_ref_values(
                assignment.non_available_member_ids,
                entry.id,
                member.id,
            )
    for session_record in ExamSession.query.filter(ExamSession.non_available_member_ids.like(f"%potential:{entry.id}%")).all():
        session_record.non_available_member_ids = replace_potential_entry_ref_values(
            session_record.non_available_member_ids,
            entry.id,
            member.id,
        )


def active_member_errors_from_potential_entry(entry):
    member = potential_entry_to_active_member(entry)
    errors = []
    if not member.title:
        errors.append("Title is required.")
    if not member.full_name:
        errors.append("Full name is required.")
    if not member.roles:
        errors.append("At least one role is required.")
    if not member.phone:
        errors.append("Phone is required.")
    if not member.email:
        errors.append("Email is required.")
    if not member.has_car:
        errors.append("Has a car is required.")
    if not member.started_in:
        errors.append("Started in is required.")
    if not member.full_address_google_maps:
        errors.append("Full address is required.")
    if not member.city:
        errors.append("City is required.")
    if not member.province:
        errors.append("Province is required.")
    if not member.country:
        errors.append("Country is required.")
    if not member.cv:
        errors.append("CV is required.")
    if not member.profile_picture:
        errors.append("Profile picture is required.")
    if not member.account_id:
        errors.append("Account ID is required.")
    if not member.account_owner:
        errors.append("Account owner is required.")
    if member.email and not EMAIL_RE.match(member.email):
        errors.append("Email must be a valid email address.")
    if member.cv and not is_valid_url(member.cv):
        errors.append("CV must be a valid http or https URL.")
    if member.profile_picture and not is_valid_url(member.profile_picture):
        errors.append("Profile picture must be a valid http or https URL.")
    if member.started_in and not YEAR_RE.match(member.started_in):
        errors.append("Started in must be a four-digit year.")
    if any(role not in ROLES for role in member.roles_list()):
        errors.append("Roles contains an invalid value.")
    if member.has_car not in {"Yes", "No"}:
        errors.append("Has a car contains an invalid value.")
    return member, errors


