@staff_bp.route("/potential-entries/<int:entry_id>/archive", methods=["POST"])
@login_required
def archive_potential_entry(entry_id):
    if not validate_csrf():
        flash("Security token expired. Please try again.", "error")
        return redirect(url_for("staff.potential_entries"))

    entry = PotentialEntry.query.get_or_404(entry_id)
    archive_status = request.form.get("archive_status", "").strip()
    if archive_status != "Archive":
        if entry.status == "Entry accepted (on hold)" and archive_status == "Interview confirmed":
            set_potential_entry_status(entry, "Interview confirmed")
            entry.reactivation_date = ""
            db.session.commit()
            flash("Potential entry saved.", "success")
            return redirect(url_for("staff.potential_entries"))
        if entry.status == "Entry accepted (on hold)" and archive_status == "Entry rejected":
            if potential_entry_has_exam_session_assignments(entry.id):
                return potential_entry_rejection_block_redirect(entry)
            set_potential_entry_status(entry, "Entry rejected")
            entry.is_rejected = True
            entry.rejected_on = datetime.now(timezone.utc)
            entry.reactivation_date = ""
            db.session.commit()
            flash("Potential entry saved.", "success")
            return redirect(url_for("staff.potential_entries"))
        if entry.status == "Entry rejected" and archive_status == "CV to be reviewed":
            set_potential_entry_status(entry, "CV to be reviewed")
            entry.is_rejected = False
            entry.rejected_on = None
            db.session.commit()
            flash("Potential entry saved.", "success")
            return redirect(url_for("staff.potential_entries"))
        flash("Potential entry saved.", "success")
        return redirect(url_for("staff.potential_entries"))
    if entry.status == "Entry rejected":
        set_potential_entry_status(entry, "Archived rejected entry")
        entry.is_rejected = True
    elif entry.status in {"Entry accepted (on hold)", "Onboarding finalised"}:
        set_potential_entry_status(entry, "Archived accepted entry")
    else:
        flash("Only rejected or finalised potential entries can be archived.", "error")
        return redirect(url_for("staff.potential_entries"))

    db.session.commit()
    flash("Potential entry archived.", "success")
    return redirect(url_for("staff.potential_entries"))


@staff_bp.route("/potential-entries/<int:entry_id>/reactivate", methods=["POST"])
@login_required
def reactivate_potential_entry(entry_id):
    if not validate_csrf():
        flash("Security token expired. Please try again.", "error")
        return redirect(url_for("staff.potential_entries", show_archived=1))

    entry = PotentialEntry.query.get_or_404(entry_id)
    if entry.status not in POTENTIAL_ARCHIVED_STATUSES:
        flash("Only archived potential entries can be reactivated.", "error")
        return redirect(url_for("staff.potential_entries"))

    reactivation_status = request.form.get("reactivation_status", "").strip()
    if reactivation_status not in POTENTIAL_REACTIVATION_STATUS_OPTIONS:
        flash("Please select a valid reactivation status.", "error")
        return redirect(url_for("staff.potential_entries", show_archived=1, open_staff_modal=f"potential-entry-{entry.id}"))
    if reactivation_status == "Entry rejected" and potential_entry_has_exam_session_assignments(entry.id):
        return potential_entry_rejection_block_redirect(entry)

    set_potential_entry_status(entry, reactivation_status)
    entry.is_rejected = reactivation_status == "Entry rejected"
    if entry.is_rejected:
        if not entry.rejected_on:
            entry.rejected_on = datetime.now(timezone.utc)
    else:
        entry.rejected_on = None
    db.session.commit()
    flash("Potential entry reactivated.", "success")
    return redirect(url_for("staff.potential_entries"))


@staff_bp.route("/potential-entries/<int:entry_id>/delete", methods=["POST"])
@login_required
def delete_rejected_potential_entry(entry_id):
    if not validate_csrf():
        flash("Security token expired. Please try again.", "error")
        return redirect(url_for("staff.potential_entries", show_rejected=1))

    entry = PotentialEntry.query.get_or_404(entry_id)
    if not entry.is_rejected and entry.status not in {"Archived accepted entry", "Archived rejected entry"}:
        flash("Only archived or rejected potential entries can be permanently deleted.", "error")
        return redirect(url_for("staff.potential_entries"))
    if not is_valid_rejected_potential_entry_delete_password():
        flash("Potential entry delete password is not valid.", "error")
        return redirect(url_for("staff.potential_entries", show_rejected=1))

    success_message = (
        "Potential entry permanently deleted."
        if entry.status == "Archived accepted entry"
        else "Rejected potential entry permanently deleted."
    )
    db.session.delete(entry)
    db.session.commit()
    flash(success_message, "success")
    return redirect(url_for("staff.potential_entries", show_rejected=1))


@staff_bp.route("/potential-entries/<int:entry_id>/accept", methods=["POST"])
@login_required
def accept_potential_entry(entry_id):
    if not validate_csrf():
        flash("Security token expired. Please try again.", "error")
        return redirect(url_for("staff.potential_entries"))

    entry = PotentialEntry.query.get_or_404(entry_id)
    errors = validate_member_form(request.form, allow_archived=False, require_complete=True)
    if errors:
        draft_errors = apply_partial_potential_acceptance_draft_form(entry, request.form)
        db.session.commit()
        for error in errors:
            flash(error, "error")
        for error in draft_errors:
            if error not in errors:
                flash(error, "error")
        return redirect(url_for("staff.potential_entries", open_staff_modal=f"accept-potential-entry-{entry.id}"))

    member = AcademicStaff()
    member.interview = entry.interview
    apply_form(member, request.form)
    db.session.add(member)
    db.session.flush()
    promote_potential_entry_exam_session_assignments(entry, member)
    db.session.delete(entry)
    db.session.commit()
    flash("Potential entry accepted and moved to academic staff.", "success")
    return redirect(url_for("staff.index"))


